"""Fixed-cell native cleanup bank; RO-style world item collects at contact."""
from pathlib import Path
import json,hashlib,shutil
P=Path(__file__).resolve().parent;root=P.parents[2]
for name in ['sprite-clip-clock.cjs']:shutil.copyfile(root/'tools'/name,P/'inputs'/name)
data={'images':['candidates/N-descent-cleanup-attempt1.png','candidates/N-recovery-cleanup-attempt1.png'],'source_sha256':[hashlib.sha256((P/n).read_bytes()).hexdigest() for n in ['candidates/N-descent-cleanup-attempt1.png','candidates/N-recovery-cleanup-attempt1.png']],'durations':[90]*15+[550],'events':[{'id':'contact','at':720},{'id':'collect','at':720},{'id':'complete','at':1900}],'world_item':{'position':[224,430],'collect_ms':720,'scope':'Authored preview event, not recovered hidden grasp timing or actual inventory mutation. World item stays fixed until collected; no item baked into body or carried through recovery.'},'mapping':[[i//8,i%8] if i<15 else [0,0] for i in range(16)],'neutral_return_lock':'Exposure15reuses complete native exposure0, not a fitted/warped head or shoe patch;16exposures,15distinct body drawings, full neutral return exact','transform':[1,0,0,1,0,0],'origin_policy':'Fixed384x512cells; no per-frame scale, foot fit or row-origin correction','body_scope':'Native cleanup of24-variant mesh-conditioned smooth sequence; not a claim that raw morph ghost arms passed image review'}
(P/'pickup-contract.json').write_text(json.dumps(data,indent=2)+'\n')
html='''<!doctype html><html lang="th"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>ท่าก้ม16เฟรม · ตรวจใหม่</title><style>body{font:16px system-ui;background:#20252d;color:#eee;margin:24px}canvas{background:#292b30;max-width:100%;height:auto}button,select,input{font:inherit;margin:6px}p{max-width:1000px;line-height:1.5}</style><h1>ท่าก้ม16เฟรม · ตรวจทั้งท่า</h1><p>ซ้าย: ชุดที่แจ้งว่ายังเด้ง · ขวา: ชุดแก้จังหวะและแขน · วัตถุอยู่กับพื้นจนถึงจังหวะเก็บ แล้วกลับมือเปล่า</p><canvas id="view" width="768" height="512"></canvas><p><button id="play">เล่น</button><button id="prev">ก่อนหน้า</button><button id="next">ถัดไป</button><input id="frame" type="range" min="0" max="15" value="0"><select id="speed"><option value="1">1×</option><option value="0.25">0.25×</option></select><label><input id="loop" type="checkbox">วนดู</label><label><input id="grid" type="checkbox">กริด</label><label><input id="item" type="checkbox">จำลองeventของตก</label></p><p id="status"></p><script src="inputs/sprite-clip-clock.cjs"></script><script>
const D=__DATA__,$=x=>document.getElementById(x),ctx=$('view').getContext('2d'),off=document.createElement('canvas');off.width=384;off.height=512;const ox=off.getContext('2d'),clock=new SpriteClipClock({...D,loop:false});let images=[],before=[],k=0,last=0;const starts=D.durations.map((_,i)=>D.durations.slice(0,i).reduce((a,b)=>a+b,0));
function gem(c,x,y){c.save();c.translate(x,y);c.lineWidth=1;c.strokeStyle='#07515e';const poly=(points,fill)=>{c.beginPath();points.forEach(([a,b],i)=>i?c.lineTo(a,b):c.moveTo(a,b));c.closePath();c.fillStyle=fill;c.fill();c.stroke()};poly([[-7,-12],[5,-14],[10,-3],[5,12],[-5,14],[-10,3]],'#198ca2');poly([[-7,-12],[0,-4],[-10,3]],'#62dce7');poly([[5,-14],[0,-4],[-7,-12]],'#b2f5f2');poly([[5,-14],[10,-3],[0,-4]],'#45d2e0');poly([[0,-4],[10,-3],[5,12]],'#11849a');poly([[0,-4],[5,12],[-5,14],[-10,3]],'#22b9cb');c.restore()}
function single(index,item=true){ox.setTransform(1,0,0,1,0,0);ox.clearRect(0,0,384,512);if(item&&starts[index]<D.world_item.collect_ms)gem(ox,...D.world_item.position);const[bank,n]=D.mapping[index];ox.drawImage(images[bank],n%4*384,Math.floor(n/4)*512,384,512,0,0,384,512)}
function draw(){ctx.clearRect(0,0,768,512);ctx.drawImage(before[k],0,0);single(k,$('item').checked);ctx.drawImage(off,384,0);if($('grid').checked){ctx.strokeStyle='#ffffff25';ctx.beginPath();for(let x=0;x<=768;x+=32){ctx.moveTo(x,0);ctx.lineTo(x,512)}for(let y=0;y<=512;y+=32){ctx.moveTo(0,y);ctx.lineTo(768,y)}ctx.stroke()}$('frame').value=k;$('play').textContent=clock.running?'หยุด':'เล่น';$('status').textContent=`เฟรม${k+1}/16 · ${D.durations[k]}ms · ${starts[k]}ms · ${starts[k]<D.world_item.collect_ms?'ก่อนเก็บ':'หลังเก็บ'}`}
function select(i){k=i;clock.seek(starts[i]);draw()}$('frame').oninput=()=>select(+$('frame').value);$('prev').onclick=()=>select(Math.max(0,k-1));$('next').onclick=()=>select(Math.min(15,k+1));$('grid').onchange=draw;$('item').onchange=draw;$('play').onclick=()=>{if(clock.running)clock.cancel();else{clock.clip.loop=$('loop').checked;clock.start()}last=performance.now();draw()};
function tick(t){if(clock.running){k=clock.advance((t-last)*+$('speed').value).frame;draw()}last=t;requestAnimationFrame(tick)}function load(s){return new Promise((ok,no)=>{let im=new Image();im.onload=()=>ok(im);im.onerror=no;im.src=s})}
Promise.all([Promise.all(D.images.map(load)),Promise.all(Array.from({length:16},(_,i)=>load('../pickup-contact-v49/renders/corrected/'+String(i).padStart(2,'0')+'.png')))]).then(([a,b])=>{images=a;before=b;draw();window.READY=true;requestAnimationFrame(tick)});window.study={data:D,clock,select,frame(i,item=true){single(i,item);return off.toDataURL('image/png')}};
</script></html>'''
(P/'pickup-review.html').write_text(html.replace('__DATA__',json.dumps(data,separators=(',',':'))))
